//! The TS app-migration ledger (`AppMigration`, D14).
//!
//! In compat mode Rust never writes to the ledger. Boot requires every id in
//! `crates/server/data/required-ts-migrations.json` (generated by `pnpm db:export-migration-ids`
//! from `scripts/run-migrations.ts`); `AUTODUCK_ENV=dev` only warns, because `dev.db` predates
//! the newest TS migrations.

use std::sync::OnceLock;

use serde::Deserialize;
use sqlx::SqliteConnection;

const REQUIRED_JSON: &str = include_str!("../../data/required-ts-migrations.json");

/// Marker row that, together with `AUTODUCK_SCHEMA_MODE=owned`, lets Rust own the schema.
pub const PONR_MARKER_ID: &str = "rs-ponr";
/// `AppMigration` ids starting with this mark a sanitised staging copy (plan Phase 3, guard 5).
pub const STAGING_SENTINEL_PREFIX: &str = "staging-sanitized-";

#[derive(Deserialize)]
struct RequiredFile {
    format: String,
    ids: Vec<String>,
}

/// The required ids, in `run-migrations.ts` order.
pub fn required_ts_migrations() -> &'static [String] {
    static IDS: OnceLock<Vec<String>> = OnceLock::new();
    IDS.get_or_init(|| {
        let file: RequiredFile = serde_json::from_str(REQUIRED_JSON)
            .expect("crates/server/data/required-ts-migrations.json is valid JSON");
        assert_eq!(file.format, "autoduck-required-ts-migrations/1");
        file.ids
    })
}

/// Every id in the ledger.
pub async fn applied_ids(conn: &mut SqliteConnection) -> Result<Vec<String>, sqlx::Error> {
    sqlx::query_scalar!(r#"SELECT "id" AS "id!" FROM "AppMigration" ORDER BY "id""#)
        .fetch_all(conn)
        .await
}

/// Required ids missing from `applied`, in declaration order.
pub fn missing_required(applied: &[String]) -> Vec<String> {
    required_ts_migrations()
        .iter()
        .filter(|id| !applied.contains(id))
        .cloned()
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_list_matches_run_migrations() {
        let ids = required_ts_migrations();
        assert!(ids.len() >= 16);
        assert_eq!(ids[0], "2026-04-23-001-shield-charges-v1");
        assert!(
            ids.iter()
                .any(|id| id == "2026-10-05-001-cosmetics-v2-catalog")
        );
        // Every id must be one the TS runner can write: no rs-* or staging ids.
        assert!(
            ids.iter()
                .all(|id| !id.starts_with("rs-") && !id.starts_with(STAGING_SENTINEL_PREFIX))
        );
    }

    #[test]
    fn missing_is_ordered() {
        let mut applied: Vec<String> = required_ts_migrations().to_vec();
        let last = applied.pop().unwrap();
        applied.remove(0);
        assert_eq!(
            missing_required(&applied),
            vec![required_ts_migrations()[0].clone(), last]
        );
    }
}
